import isNumber from "../utils/isNumber.js";
import isString from "../utils/isString.js";
export const cryptoNames = ["Ed25519", "ECDSA", "Schnorr"];
export const isCryptoName = (value) => {
    return isString(value) && cryptoNames.includes(value);
};
export const indexOfCrypto = (name) => {
    return cryptoNames.indexOf(name);
};
export const isCryptoIndex = (value) => {
    return isNumber(value) && Number.isInteger(value) && value >= 0 && value < cryptoNames.length;
};
export const parseCryptoIndex = (s) => {
    const index = parseInt(s, 10);
    if (isCryptoIndex(index) === false) {
        throw new Error("Invalid Crypto index");
    }
    return index;
};
